def _follow60_canary_enabled_for_account(account_id: str | None) -> bool:
    """Consult the validated runtime binding; never a compile-time allowlist."""
    try:
        from follow_60s_canary import enabled_for_account

        return bool(enabled_for_account(account_id))
    except Exception:
        return False


def _follow60_canary_evaluation_hold_allowed(
    *,
    account_id: str | None,
    runtime_context: dict[str, Any] | None,
) -> bool:
    """Keep operator-evaluation holds exclusive to real canary bindings."""
    return bool(
        _follow60_canary_enabled_for_account(account_id)
        and str(dict(runtime_context or {}).get("binding_kind") or "").strip().lower()
        == "canary"
    )


def _follow60_evaluation_barrier_due(
    *,
    canary_active: bool,
    stage_receipts_enabled: bool,
    cycle_complete: bool,
    completed_new_cycles: int,
    max_new_cycles: int,
) -> bool:
    """Pure, account-neutral gate preventing an eleventh canary candidate."""
    return bool(
        canary_active
        and stage_receipts_enabled
        and cycle_complete
        and int(max_new_cycles or 0) > 0
        and int(completed_new_cycles or 0) >= int(max_new_cycles or 0)
    )


def _follow60_startup_replay_decision(
    ledger_ack: dict[str, Any] | None,
) -> str:
    """Classify replay before installing components or touching the device."""
    ledger = dict(ledger_ack or {})
    if not ledger:
        return "continue"
    if (
        not bool(ledger.get("ok"))
        or str(ledger.get("schema") or "")
        != "FOLLOW60_RUN_SCOPED_CYCLE_LEDGER_V1"
    ):
        return "invalid"
    if bool(ledger.get("barrier_reached")) or not bool(
        ledger.get("next_candidate_permitted", True)
    ):
        return "stop_at_barrier"
    return "continue"


def _follow60_evaluation_terminal_contract(
    *,
    barrier_due: bool,
    cycle_complete: bool,
    canonical_count_match: bool,
    follow_verified: bool,
    mute_posts_verified: bool,
    mute_stories_verified: bool,
    like_terminal_safe: bool,
    return_ct_exact: bool,
    critical_receipts_acknowledged: bool,
    critical_outbox_pending: int,
    action_in_progress: bool,
    next_candidate_started: bool,
) -> dict[str, Any]:
    """Fail-closed proof for the evaluation-only successful terminal."""

    checks = {
        "barrier_due": bool(barrier_due),
        "cycle_complete": bool(cycle_complete),
        "canonical_count_match": bool(canonical_count_match),
        "follow_verified": bool(follow_verified),
        "mute_posts_verified": bool(mute_posts_verified),
        "mute_stories_verified": bool(mute_stories_verified),
        "like_terminal_safe": bool(like_terminal_safe),
        "return_ct_exact": bool(return_ct_exact),
        "critical_receipts_acknowledged": bool(critical_receipts_acknowledged),
        "critical_outbox_empty": int(critical_outbox_pending or 0) == 0,
        "no_action_in_progress": not bool(action_in_progress),
        "no_next_candidate_started": not bool(next_candidate_started),
    }
    failed = [name for name, passed in checks.items() if not passed]
    return {
        "ok": not failed,
        "terminal_status": (
            "completed_waiting_operator_evaluation" if not failed else ""
        ),
        "reason": (
            "follow60_evaluation_barrier_terminal_ready"
            if not failed
            else f"follow60_evaluation_barrier_unsafe:{failed[0]}"
        ),
        "checks": checks,
        "failed_checks": failed,
        "critical_outbox_pending": int(critical_outbox_pending or 0),
    }




def _pre_follow_gap_log(
    event: str,
    *,
    target_username: str = "",
    candidate_username: str = "",
    source_profile_username: str = "",
    visual_candidate_id: str = "",
    phase: str = "",
    started_at: float | None = None,
    duration_ms: float | None = None,
    blocking_step: str = "",
    probe_count: Any = None,
    used_cached_context: bool | None = None,
    fallback_used: bool | None = None,
    surface_type: str = "",
    safe_to_tap: bool | None = None,
    follow_state: str = "",
    pending_state: Any = None,
    is_private: bool | None = None,
    reason: str = "",
    **fields: Any,
) -> None:
    """Structured pre-follow timing log. Instrumentation-only; no decisions."""
    payload: dict[str, Any] = {
        "target_username": str(target_username or source_profile_username or ""),
        "candidate_username": str(candidate_username or target_username or ""),
        "source_profile_username": str(source_profile_username or ""),
        "visual_candidate_id": str(visual_candidate_id or ""),
        "phase": str(phase or ""),
        "blocking_step": str(blocking_step or ""),
        "surface_type": str(surface_type or ""),
        "reason": str(reason or ""),
    }
    if started_at is not None:
        try:
            payload["duration_ms"] = round((time.perf_counter() - float(started_at)) * 1000.0, 2)
        except Exception:
            payload["duration_ms"] = 0.0
    elif duration_ms is not None:
        payload["duration_ms"] = round(float(duration_ms), 2)
    if probe_count is not None:
        payload["probe_count"] = probe_count
    if used_cached_context is not None:
        payload["used_cached_context"] = bool(used_cached_context)
    if fallback_used is not None:
        payload["fallback_used"] = bool(fallback_used)
    if safe_to_tap is not None:
        payload["safe_to_tap"] = bool(safe_to_tap)
    if follow_state:
        payload["follow_state"] = str(follow_state)
    if pending_state is not None:
        payload["pending_state"] = pending_state
    if is_private is not None:
        payload["is_private"] = bool(is_private)
    for key, value in fields.items():
        key_l = str(key).lower()
        if any(marker in key_l for marker in ("token", "password", "secret")):
            continue
        payload[key] = value
    try:
        log("info", event, **payload)
    except Exception:
        pass


def _private_skip_fast_path_handle(
    d: Any,
    *,
    target_username: str,
    candidate_username: str,
    source_profile_username: str,
    visual_candidate_id: str,
    dont_follow_private_accounts: bool,
    profile_already_open: bool,
    profile_username_matches: bool = True,
    pkg: str = "",
    run_id: Any = None,
    source_account_context: str = "",
    return_func: Any | None = None,
) -> dict[str, Any]:
    """Early no-tap private-account skip before heavier pre-follow guards."""
    t0 = time.perf_counter()
    cand = str(candidate_username or "").strip().lstrip("@")
    src = str(source_profile_username or target_username or "").strip()
    vcid = str(visual_candidate_id or "").strip()
    base_fields = {
        "target_username": str(target_username or src or ""),
        "candidate_username": cand,
        "source_profile_username": src,
        "visual_candidate_id": vcid,
        "private_signal": "",
        "proof_method": "",
        "fallback_used": False,
        "safe_to_skip": False,
        "return_ok": False,
    }

    def _emit(event: str, **kw: Any) -> None:
        payload = dict(base_fields)
        payload.update(kw)
        payload["duration_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
        try:
            log("info", event, **payload)
        except Exception:
            pass

    _emit("private_skip_fast_path_started")

    if not dont_follow_private_accounts:
        _emit(
            "private_skip_fast_path_rejected",
            reason="private_follow_allowed_by_setting",
            fallback_used=True,
        )
        _emit(
            "private_skip_fast_path_completed",
            reason="private_follow_allowed_by_setting",
            fallback_used=True,
        )
        return {"handled": False, "reason": "private_follow_allowed_by_setting"}
    if not profile_already_open:
        _emit(
            "private_skip_fast_path_rejected",
            reason="profile_not_confirmed_open",
            fallback_used=True,
        )
        _emit(
            "private_skip_fast_path_completed",
            reason="profile_not_confirmed_open",
            fallback_used=True,
        )
        return {"handled": False, "reason": "profile_not_confirmed_open"}
    if not cand or not profile_username_matches:
        reason = "profile_username_mismatch" if cand else "candidate_username_missing"
        _emit("private_skip_fast_path_rejected", reason=reason, fallback_used=True)
        _emit("private_skip_fast_path_completed", reason=reason, fallback_used=True)
        return {"handled": False, "reason": reason}

    mono_capture: dict[str, Any] | None = None
    try:
        from follow_60s_canary import enabled as _follow_60s_canary_enabled

        if _follow_60s_canary_enabled("opening_follow_composite"):
            try:
                from follow60_ordering_v2_shadow import enabled_for_account

                _prepare_ordering_v2_evidence = bool(
                    enabled_for_account(str(source_account_context or ""))
                )
            except Exception:
                _prepare_ordering_v2_evidence = False
            mono_capture = acquire_pre_follow_mono_capture(
                d,
                follower_username=cand,
                expected_package=str(pkg or ""),
                prepare_ordering_v2_evidence=_prepare_ordering_v2_evidence,
            )
    except Exception:
        mono_capture = None
    mono_private = dict((mono_capture or {}).get("private_probe_payload") or {})
    mono_positive_surface = bool(
        (mono_capture or {}).get("ok")
        and (mono_capture or {}).get("exact_identity")
        and (mono_capture or {}).get("profile_surface")
        and (mono_capture or {}).get("follow_cta_positive")
        and (mono_capture or {}).get("package_exact")
        and str((mono_capture or {}).get("activity") or "").strip()
        and (mono_capture or {}).get("public_profile_proven")
    )
    if mono_positive_surface:
        probe = {
            **mono_private,
            "private_profile_detected": bool(
                mono_private.get("private_profile_detected")
            ),
            "reject": bool(mono_private.get("private_profile_detected")),
            "reason": (
                "candidate_rejected_private_account"
                if mono_private.get("private_profile_detected")
                else "mono_capture_public_ready"
            ),
            "probe_ms": float((mono_capture or {}).get("duration_ms") or 0.0),
            "hierarchy_fallback_used": False,
        }
    else:
        probe = visual_candidate_pre_follow_private_gate(
            d,
            source_profile_username=src or None,
            dont_follow_private_accounts=True,
            follower_username=cand,
            visual_candidate_id=vcid,
            prior_private_probe=None,
        )
    private_signal = str(probe.get("detection_method") or "none")
    proof_method = (
        "pre_follow_mono_capture"
        if mono_positive_surface
        else "visual_candidate_pre_follow_private_gate"
    )
    safe_to_skip = bool(probe.get("reject")) and bool(probe.get("private_profile_detected"))
    if not safe_to_skip:
        used_public_mono = bool(
            mono_positive_surface
            and not bool(probe.get("private_profile_detected"))
        )
        if used_public_mono:
            _emit(
                "pre_follow_mono_capture_public_reused",
                private_signal=private_signal,
                proof_method=proof_method,
                fallback_used=False,
                reason="mono_capture_public_ready",
                dump_count=1,
                screenshots=0,
                retries=0,
            )
        else:
            _emit(
                "private_skip_fast_path_rejected",
                private_signal=private_signal,
                proof_method=proof_method,
                fallback_used=True,
                reason=str(probe.get("reason") or "private_not_detected"),
            )
        _emit(
            "private_skip_fast_path_completed",
            private_signal=private_signal,
            proof_method=proof_method,
            fallback_used=not used_public_mono,
            reason=str(probe.get("reason") or "private_not_detected"),
        )
        return {
            "handled": False,
            "reason": str(probe.get("reason") or "private_not_detected"),
            "probe": probe,
            "mono_capture": mono_capture,
        }

    _emit(
        "private_skip_fast_path_detected",
        private_signal=private_signal,
        proof_method=proof_method,
        fallback_used=False,
        safe_to_skip=True,
        reason="private_account",
    )
    try:
        mark_visual_follow_target_processed(
            source_profile_username=src,
            target_username=cand,
            visual_candidate_id=vcid,
            status="skipped_private",
            follow_verified=False,
            follow_request_pending=False,
            run_id=str(run_id or ""),
            source_account_context=str(source_account_context or ""),
            metadata={
                "skip_reason": "private_account",
                "fast_path": "private_skip_fast_path",
                "private_signal": private_signal,
                "proof_method": proof_method,
            },
        )
    except Exception:
        pass

    _emit(
        "private_skip_fast_path_return_started",
        private_signal=private_signal,
        proof_method=proof_method,
        safe_to_skip=True,
        reason="private_account",
    )
    ret = return_func or return_to_followers_list
    return_ok = False
    return_how = ""
    try:
        return_ok, return_how = ret(d, src, pkg)
    except Exception as exc:
        return_ok = False
        return_how = f"exception:{type(exc).__name__}"
    _emit(
        "private_skip_fast_path_return_completed",
        private_signal=private_signal,
        proof_method=proof_method,
        safe_to_skip=True,
        return_ok=bool(return_ok),
        reason="private_account",
        how=str(return_how or ""),
    )
    _emit(
        "private_skip_fast_path_completed",
        private_signal=private_signal,
        proof_method=proof_method,
        fallback_used=False,
        safe_to_skip=True,
        return_ok=bool(return_ok),
        reason="private_account",
    )
    return {
        "handled": True,
        "reason": "private_account",
        "return_ok": bool(return_ok),
        "return_how": str(return_how or ""),
        "probe": probe,
        "private_signal": private_signal,
        "proof_method": proof_method,
    }


def _record_follow60_ordering_v2_shadow_from_existing_capture(
    mono_capture: dict[str, Any] | None,
    *,
    account_id: str,
    run_id: str,
    request_id: str,
    candidate_username: str,
    source_profile_username: str,
    visual_candidate_id: str,
    business_session_id: str = "",
    attempt_id: int = 0,
    binding_kind: str = "",
    worker_sha: str = "",
    target_id: str = "",
    action_id: str = "",
    business_evidence: dict[str, Any] | None = None,
    expected_binding: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Start one Ordering V2 shadow context without acquiring or changing UI state."""
    try:
        from follow60_ordering_v2_shadow import (
            begin_candidate_shadow,
        )

        return begin_candidate_shadow(
            mono_capture,
            account_id=account_id,
            run_id=run_id,
            request_id=request_id,
            business_session_id=business_session_id,
            attempt_id=attempt_id,
            binding_kind=binding_kind,
            worker_sha=worker_sha,
            target_id=target_id,
            candidate_username=candidate_username,
            source_profile_username=source_profile_username,
            visual_candidate_id=visual_candidate_id,
            action_id=action_id or visual_candidate_id,
            business_evidence=business_evidence,
            expected_binding=expected_binding,
        )
    except Exception as exc:
        # Shadow telemetry must never affect Follow60 V1.
        try:
            log(
                "warning",
                "follow60_ordering_v2_shadow_failed_open",
                account_id=str(account_id or ""),
                run_id=str(run_id or ""),
                candidate_username=str(candidate_username or ""),
                exception_type=type(exc).__name__,
            )
        except Exception:
            pass
        return None


# Real DM sends per worker process (pairs with SEND_DM_MAX_PER_RUN).
_RUNTIME_REAL_DM_SENT_COUNT: int = 0
# Successful follows this process (pairs with FOLLOW_MAX_PER_RUN).
_RUNTIME_FOLLOW_COUNT: int = 0
_RUNTIME_FOLLOWED_USERNAMES: set[str] = set()
# Follower rows already selected in followers-list engine (same run).
_RUNTIME_SEEN_FOLLOWER_USERNAMES: set[str] = set()
# Opens that resolved username on-profile but did not complete follow (anti-loop).
_RUNTIME_FOLLOWERS_POST_RESOLVE_STREAK: dict[str, int] = {}
# CT followers-list engine: usernames for which perform_follow_safe has returned this process.
_RUNTIME_CT_LIST_FOLLOW_TAP_ATTEMPTED_USERNAMES: set[str] = set()
# perform_follow_safe returned follow_started but no follow_tap_sent (per fkey, this run).
_CT_FOLLOW_NO_TAP_AFTER_START_COUNT: dict[str, int] = {}
# Candidates that returned failed_no_follow_tap this run — never reopen without a successful tap.
_RUNTIME_FAILED_NO_FOLLOW_TAP_FKEY: set[str] = set()
# Monotonic clock: deadline tracking for one CT-list candidate (survives profile reopens until tap or clear).
_CT_CANDIDATE_ATTEMPT_STARTED_MONO: float | None = None
_CT_CANDIDATE_ATTEMPT_FKEY: str | None = None
_RUNTIME_INTERACTED_USERNAMES: set[str] = set()
_RUNTIME_UNFOLLOWED_USERNAMES: set[str] = set()
_RUNTIME_SKIPPED_USERNAMES: set[str] = set()
_VISUAL_FOLLOWERS_OPEN_COUNT_THIS_SESSION: int = 0
_FOLLOW_SETTINGS_CACHE: dict[str, Any] = {}
_SESSION_SOCIAL_ID: str = ""
_SESSION_COUNTERS: dict[str, int] = {
    "follows": 0,
    "unfollows": 0,
    "likes": 0,
    "pm": 0,
    "interactions": 0,
    "successful_interactions": 0,
}


def _follow_settings_for_account(account_id: str | None) -> Any | None:
    """Account Follow settings, cached for this runner session."""
    aid = str(account_id or "").strip()
    if not aid:
        return None
    if aid in _FOLLOW_SETTINGS_CACHE:
        return _FOLLOW_SETTINGS_CACHE[aid]
    try:
        from follow_settings import load_follow_settings

        settings = load_follow_settings(aid, ensure_row=False)
    except Exception as exc:
        log(
            "warning",
            "follow_settings_load_failed_defaults_used",
            account_id=aid,
            dont_follow_private_accounts=True,
            error=str(exc)[:300],
        )
        return None
    _FOLLOW_SETTINGS_CACHE[aid] = settings
    return settings


def _dont_follow_private_accounts_for_account(account_id: str | None) -> bool:
    """Account setting, default-safe: private profiles are skipped when settings are missing."""
    settings = _follow_settings_for_account(account_id)
    if settings is None:
        return True
    return bool(getattr(settings, "dont_follow_private_accounts", True))


def _seconds_since_dm_sent_row(row: dict) -> float | None:
    """Wall-clock seconds since last send timestamp on target row, if any."""
    for key in ("dm_sent_at", "processed_at", "updated_at"):
        raw = row.get(key)
        if not raw:
            continue
        try:
            ts = str(raw).replace("Z", "+00:00")
            dt = datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return (datetime.now(timezone.utc) - dt).total_seconds()
        except Exception:
            continue
    return None


def _seconds_since_follow_row(row: dict) -> float | None:
    """Hours since last follow timestamp on target row, if any."""
    for key in ("followed_at", "updated_at", "processed_at"):
        raw = row.get(key)
        if not raw:
            continue
        try:
            ts = str(raw).replace("Z", "+00:00")
            dt = datetime.fromisoformat(ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return (datetime.now(timezone.utc) - dt).total_seconds() / 3600.0
        except Exception:
            continue
    return None


def _phase(name: str, phase_start: float) -> float:
    elapsed_ms = (time.perf_counter() - phase_start) * 1000
    log("info", "phase_timing", phase=name, elapsed_ms=round(elapsed_ms, 2))
    return time.perf_counter()


def _startup_timing_log(
    event: str,
    started_at: float,
    *,
    phase: str,
    substep: str,
    source: str,
    **fields: Any,
) -> None:
    try:
        log(
            "info",
            event,
            duration_ms=round((time.perf_counter() - started_at) * 1000.0, 2),
            phase=str(phase or ""),
            substep=str(substep or ""),
            source=str(source or ""),
            **fields,
        )
    except Exception:
        pass


def _current_package_safe(d: Any) -> str:
    try:
        current = d.app_current()
        return str((current or {}).get("package") or "").strip()
    except Exception:
        return ""


def _prepare_device_for_account_identity_preflight(
    d: Any,
    *,
    expected_package: str,
    expected_account_username: str,
    account_id: str | None,
    run_id: str | None,
) -> Any | None:
    """Wake/unlock, then restore and prove the exact clone before identity."""
    from account_identity_guard import (
        AccountIdentityCheckResult,
        ensure_preflight_device_unlocked,
    )

    keyguard_block = ensure_preflight_device_unlocked(
        d,
        account_id=account_id,
        run_id=run_id,
    )
    if keyguard_block is not None:
        return keyguard_block

    package = str(expected_package or "").strip()
    if not package:
        return AccountIdentityCheckResult(
            ok=False,
            expected_account_username=expected_account_username,
            failure_reason="expected_instagram_package_missing",
            verification_method="preflight_exact_package_restore",
        )

    if _current_package_safe(d) != package:
        app_start(d, package)
        deadline = time.monotonic() + max(
            0.1,
            float(getattr(config, "APP_START_WAIT_S", 2.0)),
        )
        while _current_package_safe(d) != package and time.monotonic() < deadline:
            time.sleep(0.1)

    if _current_package_safe(d) != package or not verify_app_foreground(d, package):
        return AccountIdentityCheckResult(
            ok=False,
            expected_account_username=expected_account_username,
            failure_reason="expected_instagram_package_not_foreground_after_unlock",
            verification_method="preflight_exact_package_restore",
            meta={"expected_package": package, "actual_package": _current_package_safe(d)},
        )
    return None


def _log_phase_budget(phase: str, elapsed_ms: float, expected_budget_ms: float) -> None:
    if elapsed_ms > expected_budget_ms:
        log(
            "warning",
            "phase_budget_exceeded",
            phase=phase,
            elapsed_ms=round(elapsed_ms, 2),
            expected_budget_ms=round(expected_budget_ms, 2),
        )
        supabase_client.log_performance_event(
            action_type="phase_budget_exceeded",
            status="warning",
            target_username=None,
            payload={
                "phase": phase,
                "elapsed_ms": round(elapsed_ms, 2),
                "expected_budget_ms": round(expected_budget_ms, 2),
            },
        )


