def _safe_supabase_call(fn_name: str, *args, **kwargs):
    fn = getattr(supabase_client, fn_name)
    try:
        return fn(*args, **kwargs)
    except Exception as e:
        log("warning", "supabase_call_failed", fn=fn_name, error=str(e))
        return None


def _timed_safe_supabase_call(
    step: str,
    fn_name: str,
    *args,
    log_run_id: str | None = None,
    log_account_id: str | None = None,
    log_attempt: int = 1,
    log_record_count: int | None = None,
    return_status: bool = False,
    **kwargs,
):
    """Instrumentation-only wrapper around Supabase writes; never logs payloads."""
    safe_step = str(step or fn_name or "unknown")[:160]
    safe_fn = str(fn_name or "")[:160]
    t0 = time.perf_counter()
    base_log = {
        "step": safe_step,
        "fn_name": safe_fn,
        "attempt": int(log_attempt or 1),
        "run_id": str(log_run_id or kwargs.get("run_id") or "")[:160],
        "account_id": str(log_account_id or kwargs.get("account_id") or "")[:160],
    }
    if log_record_count is not None:
        try:
            base_log["record_count"] = int(log_record_count)
        except Exception:
            base_log["record_count"] = 0
    log("info", "supabase_persist_step_started", **base_log)
    fn = getattr(supabase_client, fn_name)
    try:
        out = fn(*args, **kwargs)
    except Exception as e:
        duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        error_code = type(e).__name__
        log(
            "warning",
            "supabase_persist_step_failed",
            **base_log,
            duration_ms=duration_ms,
            ok=False,
            error_code=error_code,
        )
        log("warning", "supabase_call_failed", fn=fn_name, error=str(e))
        if return_status:
            return {"_supabase_call_ok": False, "value": None}
        return None
    duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)
    ok = True
    if isinstance(out, dict) and "ok" in out:
        ok = bool(out.get("ok"))
    log(
        "info",
        "supabase_persist_step_completed",
        **base_log,
        duration_ms=duration_ms,
        ok=ok,
        error_code="",
    )
    if return_status:
        return {"_supabase_call_ok": ok, "value": out}
    return out


def _reset_session_counters() -> None:
    global _SESSION_COUNTERS
    _SESSION_COUNTERS = {
        "follows": 0,
        "unfollows": 0,
        "likes": 0,
        "pm": 0,
        "interactions": 0,
        "successful_interactions": 0,
    }


def _build_account_session_completion_performance_summary(
    *,
    exit_code: int,
    account_username: str,
    followers_source_username: str | None,
    target_id: str | None,
    target_selection_source: str | None,
) -> dict[str, Any]:
    summary = {
        "run_type": "account_session",
        "exit_code": int(exit_code),
        "account_username": account_username,
        "followers_source_username": followers_source_username,
        "target_id": target_id or None,
        "target_selection_source": target_selection_source,
        "session_counters": dict(_SESSION_COUNTERS),
    }
    try:
        from account_session_orchestrator import get_last_account_session_summary

        summary.update(get_last_account_session_summary())
    except Exception as exc:
        summary["phase_summary_error"] = str(exc)[:300]
    else:
        # The account-session orchestrator owns the verified Unfollow count.
        # Reconcile the generic counters at publication time because the
        # Unfollow phase runs outside the legacy per-target counter loop.
        # This is telemetry-only: it happens after every business phase and
        # cannot increase a live quota or trigger another action.
        phase_unfollows = max(0, int(summary.get("unfollow_actions_verified") or 0))
        counters = dict(summary.get("session_counters") or {})
        counted_unfollows = max(0, int(counters.get("unfollows") or 0))
        if phase_unfollows > counted_unfollows:
            missing_unfollows = phase_unfollows - counted_unfollows
            counters["unfollows"] = phase_unfollows
            counters["interactions"] = max(
                0, int(counters.get("interactions") or 0)
            ) + missing_unfollows
            counters["successful_interactions"] = max(
                0, int(counters.get("successful_interactions") or 0)
            ) + missing_unfollows
            summary["session_counters"] = counters
    if int(exit_code) != 0:
        from welcome_list_sender import get_last_welcome_list_sender_summary
        from welcome_scan_producer import get_last_welcome_scan_summary

        sender_summary = get_last_welcome_list_sender_summary()
        scan_summary = get_last_welcome_scan_summary()
        entry_decision = str(sender_summary.get("entry_surface_decision") or "").strip()
        sender_reason = str(sender_summary.get("failure_reason") or "").strip()
        scan_failure_reason = str(scan_summary.get("failure_reason") or "").strip()
        if entry_decision == "recovered_snapshot_rejected":
            summary["reason"] = entry_decision
        elif sender_reason:
            summary["reason"] = sender_reason
        elif scan_failure_reason:
            summary["reason"] = scan_failure_reason
        elif str(scan_summary.get("stop_reason") or "").strip() == "followers_surface_lost":
            summary["reason"] = "welcome_surface_unstable"
        summary["welcome_scan_stop_reason"] = scan_summary.get("stop_reason")
        summary["welcome_scan_jobs_enqueued_count"] = scan_summary.get("jobs_enqueued_count")
        summary["welcome_sender_failure_reason"] = sender_reason or None
        summary["welcome_entry_surface_decision"] = entry_decision or None
    return summary


def _session_follow_quota_exceeded() -> bool:
    caps = [
        int(getattr(config, "SESSION_TOTAL_FOLLOWS_CAP", 0) or 0),
        int(getattr(config, "SESSION_FOLLOW_LIMIT", 0) or 0),
    ]
    pos = [c for c in caps if c > 0]
    if not pos:
        return False
    return _SESSION_COUNTERS["follows"] >= min(pos)


def _runtime_follow_cap_exceeded(cap: int | None = None) -> bool:
    cap = int(cap if cap is not None else (getattr(config, "FOLLOW_MAX_PER_RUN", 5) or 0))
    return cap > 0 and _RUNTIME_FOLLOW_COUNT >= cap


def _resolve_absolute_follow_session_cap(
    *,
    current_session_count: int,
    remaining_allowance: int,
    fixed_session_cap: int | None = None,
    runtime_absolute_cap: int | None = None,
) -> int:
    """Convert a live remaining quota into an absolute per-session stop cap.

    Runtime cap inputs are refreshed between Follow sources.  Their day quota
    is therefore a *remaining* allowance, while ``_RUNTIME_FOLLOW_COUNT`` is
    cumulative for the whole account session.  Comparing the cumulative count
    directly with the refreshed allowance would stop 25/50 as soon as the DB
    reports 25 remaining.  Keep the first orchestrator goal as a ceiling and
    also honor any stricter live or explicit runtime ceiling.
    """
    current = max(0, int(current_session_count or 0))
    remaining = max(0, int(remaining_allowance or 0))
    candidates = [current + remaining]
    for value in (fixed_session_cap, runtime_absolute_cap):
        try:
            cap = int(value or 0)
        except (TypeError, ValueError):
            cap = 0
        if cap > 0:
            candidates.append(cap)
    return min(candidates)


def should_stop_for_global_follow_cap(current_count: int, cap: int | None) -> bool:
    try:
        cap_i = int(cap or 0)
    except (TypeError, ValueError):
        cap_i = 0
    if cap_i <= 0:
        return False
    try:
        current_i = max(0, int(current_count or 0))
    except (TypeError, ValueError):
        current_i = 0
    return current_i >= cap_i


_TARGET_REJECTION_STABLE_REASONS = frozenset(
    {
        "already_followed",
        "already_unfollowed",
        "already_interacted",
        "runtime_seen",
        "social_memory_blocked",
        "lifecycle_unfollowed_completed",
        "lifecycle_followed_completed",
        "lifecycle_blocked_future_follow",
        "refollow_after_unfollow_forbidden",
        "cooldown_until_active",
        "follow_max_per_run",
        "global_follow_cap_reached",
        "private_account",
        "no_follow_button",
        "cta_mismatch",
        "profile_load_failed",
        "filter_rejected",
        "stale_row",
        "unknown",
    }
)
_TARGET_REJECTION_EXAMPLES_PER_REASON = 3


def _normalize_target_rejection_reason(reason: str | None) -> str:
    raw = str(reason or "").strip().lower()
    if not raw:
        return "unknown"
    if raw in _TARGET_REJECTION_STABLE_REASONS:
        return raw
    if raw in ("runtime_already_seen", "runtime_seen_before_follow"):
        return "runtime_seen"
    if raw in ("skip_private_profile", "private_account_filter_follow_private_disabled"):
        return "private_account"
    if raw in ("persistent_active_follow_connection", "already_following", "candidate_already_connected_skip"):
        return "already_followed"
    if raw in ("runtime_already_unfollowed", "previously_unfollowed"):
        return "already_unfollowed"
    if raw in ("runtime_already_interacted", "already_interacted_recently"):
        return "already_interacted"
    if raw.startswith("persistent_preopen_already_connected") or raw.startswith(
        "persistent_postopen_already_connected"
    ):
        return "already_followed"
    if "follow_max_per_run" in raw:
        return "follow_max_per_run"
    if "global_follow_cap" in raw:
        return "global_follow_cap_reached"
    if "social_memory" in raw or raw.startswith("session_"):
        return "social_memory_blocked"
    if "private" in raw:
        return "private_account"
    if "no_blue_follow" in raw or "no_follow" in raw:
        return "no_follow_button"
    if "header_not_invite" in raw or "non_follow_cta" in raw or "cta" in raw:
        return "cta_mismatch"
    if "profile" in raw and ("failed" in raw or "load" in raw):
        return "profile_load_failed"
    if "stale" in raw or "vision_validation_rejected" in raw:
        return "stale_row"
    if "filter" in raw or "confidence_below" in raw:
        return "filter_rejected"
    return "unknown"


def _target_rejection_tracker(target_username: str) -> dict[str, Any]:
    return {
        "target_username": str(target_username or "").strip(),
        "candidates_seen_count": 0,
        "candidates_opened_count": 0,
        "follows_sent_count": 0,
        "scrolls_attempted": 0,
        "last_scroll_index": -1,
        "rejection_reason_counts": {},
        "_example_counts": {},
    }


def _target_rejection_record(
    tracker: dict[str, Any],
    *,
    reason: str,
    candidate_username: str = "",
    source_phase: str = "",
    count: int = 1,
    emit_log: bool = True,
    checkpoint: dict[str, Any] | None = None,
) -> str:
    stable = _normalize_target_rejection_reason(reason)
    n = max(1, int(count or 1))
    counts = tracker.setdefault("rejection_reason_counts", {})
    counts[stable] = int(counts.get(stable) or 0) + n
    examples = tracker.setdefault("_example_counts", {})
    examples[stable] = int(examples.get(stable) or 0) + n
    if emit_log and int(examples[stable]) <= _TARGET_REJECTION_EXAMPLES_PER_REASON:
        log(
            "info",
            "target_candidate_rejected",
            target_username=str(tracker.get("target_username") or ""),
            candidate_username=str(candidate_username or "")[:120],
            reason=stable,
            raw_reason=str(reason or "")[:160],
            source_phase=str(source_phase or "")[:80],
        )
    ck = checkpoint if isinstance(checkpoint, dict) else tracker.get("_ct_checkpoint")
    if isinstance(ck, dict) and str(candidate_username or "").strip():
        for _ in range(n):
            _ct_checkpoint_mark_rejected(
                ck,
                str(candidate_username or ""),
                reason=stable,
                source_phase=str(source_phase or ""),
            )
    return stable


def _target_rejection_summary_payload(
    tracker: dict[str, Any],
    *,
    stop_reason: str,
) -> dict[str, Any]:
    counts = dict(tracker.get("rejection_reason_counts") or {})
    rejected_count = sum(int(v or 0) for v in counts.values())
    return {
        "target_username": str(tracker.get("target_username") or ""),
        "candidates_seen_count": int(tracker.get("candidates_seen_count") or 0),
        "candidates_rejected_count": int(rejected_count),
        "rejection_reason_counts": counts,
        "scrolls_attempted": int(tracker.get("scrolls_attempted") or 0),
        "last_scroll_index": int(tracker.get("last_scroll_index") or -1),
        "stop_reason": str(stop_reason or ""),
    }


_CT_CHECKPOINT_FRESH_MS = 20 * 60 * 1000.0
_CT_CHECKPOINT_SCROLL_RESUME_OFFSET = 1
_CT_CHECKPOINT_POST_RETURN_REUSE_MS = 60_000.0
_CT_CHECKPOINT_POST_RETURN_SAFE_METHODS = frozenset(
    (
        "compact_safe_back_then_list",
        "compact_foreign_profile_back_visual_followers_list_confirmed",
        "compact_foreign_profile_fallback_then_list",
        "foreign_profile_one_safe_back_then_list",
        "compact_initial_list_confirmed",
        "already_on_followers_list",
        "fresh_candidate_proof_one_back_then_exact_ct",
    )
)


def _ct_checkpoint_utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _ct_checkpoint_stale_after_iso() -> str:
    stale_after_s = float(_CT_CHECKPOINT_FRESH_MS) / 1000.0
    return datetime.fromtimestamp(time.time() + stale_after_s, timezone.utc).isoformat()


def _ct_checkpoint_enabled() -> bool:
    return bool(getattr(config, "FOLLOW_CT_CHECKPOINT_V1_ENABLED", True))


def _ct_checkpoint_new(
    *,
    source_username: str,
    source_target_id: str = "",
    account_id: str = "",
    run_id: str = "",
) -> dict[str, Any]:
    now = time.perf_counter()
    now_iso = _ct_checkpoint_utc_now_iso()
    stale_after = _ct_checkpoint_stale_after_iso()
    # Keep V1 runtime-only, but use DB-ready field names for the future persisted V2.
    return {
        "source_username": str(source_username or "").strip(),
        "source_target_id": str(source_target_id or "").strip(),
        "account_id": str(account_id or "").strip(),
        "run_id": str(run_id or "").strip(),
        "last_run_id": str(run_id or "").strip(),
        "last_scroll_index": -1,
        "last_seen_candidate_usernames": [],
        "last_rejected_candidate_usernames": {},
        "last_private_rejected_usernames": [],
        "last_followed_candidate_username": "",
        "last_successful_candidate_at": "",
        "last_successful_candidate_at_mono": 0.0,
        "checkpoint_reason": "",
        "checkpoint_status": "active",
        "last_checkpoint_reason": "",
        "stale_after": stale_after,
        "created_at": now_iso,
        "updated_at": now_iso,
        "created_by_runtime": "python_worker",
        "created_at_mono": now,
        "updated_at_mono": now,
        "updated_at_epoch": time.time(),
        "last_visible_usernames": [],
        "last_visible_surface_generation": 0.0,
        "private_rejected_count": 0,
        "followed_count": 0,
        "rejected_count": 0,
        "seen_count": 0,
        "sequence": 0,
        "scroll_resume_planned_index": None,
        "scroll_resume_applied": False,
    }


def _ct_checkpoint_age_ms(checkpoint: dict[str, Any]) -> float:
    epoch = float(checkpoint.get("updated_at_epoch") or 0.0)
    if epoch > 0:
        return round((time.time() - epoch) * 1000.0, 2)
    updated = float(checkpoint.get("updated_at_mono") or 0.0)
    if updated <= 0:
        return 0.0
    age_s = time.perf_counter() - updated
    if age_s < 0:
        return 0.0
    return round(age_s * 1000.0, 2)


def _ct_checkpoint_last_scroll_index(checkpoint: dict[str, Any]) -> int:
    raw = checkpoint.get("last_scroll_index")
    if raw is None:
        return -1
    try:
        return int(raw)
    except (TypeError, ValueError):
        return -1


def _ct_checkpoint_common_fields(checkpoint: dict[str, Any]) -> dict[str, Any]:
    rejected_map = dict(checkpoint.get("last_rejected_candidate_usernames") or {})
    return {
        "source_username": str(checkpoint.get("source_username") or ""),
        "source_target_id": str(checkpoint.get("source_target_id") or "") or None,
        "account_id": str(checkpoint.get("account_id") or "") or None,
        "run_id": str(checkpoint.get("run_id") or "") or None,
        "last_run_id": str(checkpoint.get("last_run_id") or checkpoint.get("run_id") or "") or None,
        "scroll_index": _ct_checkpoint_last_scroll_index(checkpoint),
        "seen_count": int(checkpoint.get("seen_count") or 0),
        "rejected_count": int(checkpoint.get("rejected_count") or 0),
        "private_rejected_count": int(checkpoint.get("private_rejected_count") or 0),
        "followed_count": int(checkpoint.get("followed_count") or 0),
        "checkpoint_reason": str(
            checkpoint.get("checkpoint_reason")
            or checkpoint.get("last_checkpoint_reason")
            or ""
        ),
        "checkpoint_status": str(checkpoint.get("checkpoint_status") or "active"),
        "stale_after": str(checkpoint.get("stale_after") or "") or None,
        "updated_at": str(checkpoint.get("updated_at") or "") or None,
        "checkpoint_age_ms": _ct_checkpoint_age_ms(checkpoint),
        "fallback_used": False,
        "safe_to_resume": False,
    }


def _ct_checkpoint_emit(
    checkpoint: dict[str, Any],
    event: str,
    *,
    reason: str = "",
    **fields: Any,
) -> None:
    if not _ct_checkpoint_enabled():
        return
    payload = dict(_ct_checkpoint_common_fields(checkpoint))
    payload.update(fields)
    if reason:
        payload["reason"] = str(reason)
    try:
        log("info", event, **payload)
    except Exception:
        pass


def _ct_checkpoint_validate(
    checkpoint: dict[str, Any],
    *,
    source_username: str,
    account_id: str,
    run_id: str,
) -> tuple[bool, str]:
    if not checkpoint:
        return False, "checkpoint_missing"
    src = _norm_ig_handle(source_username)
    ck_src = _norm_ig_handle(str(checkpoint.get("source_username") or ""))
    if not src or src != ck_src:
        return False, "source_username_mismatch"
    if str(checkpoint.get("account_id") or "") != str(account_id or ""):
        return False, "account_id_mismatch"
    if str(checkpoint.get("run_id") or "") != str(run_id or ""):
        return False, "run_id_mismatch"
    age_ms = _ct_checkpoint_age_ms(checkpoint)
    if age_ms > _CT_CHECKPOINT_FRESH_MS:
        return False, "checkpoint_stale"
    return True, "ok"


def _ct_checkpoint_mark_seen(
    checkpoint: dict[str, Any],
    candidate_username: str,
    *,
    reason: str = "candidate_seen",
) -> None:
    key = _norm_ig_handle(candidate_username)
    if not key:
        return
    seen = list(checkpoint.get("last_seen_candidate_usernames") or [])
    if key not in seen:
        seen.append(key)
        checkpoint["seen_count"] = int(checkpoint.get("seen_count") or 0) + 1
    checkpoint["last_seen_candidate_usernames"] = seen[-96:]
    checkpoint["updated_at"] = _ct_checkpoint_utc_now_iso()
    checkpoint["updated_at_mono"] = time.perf_counter()
    checkpoint["updated_at_epoch"] = time.time()
    checkpoint["stale_after"] = _ct_checkpoint_stale_after_iso()
    checkpoint["checkpoint_reason"] = str(reason or "candidate_seen")
    checkpoint["last_checkpoint_reason"] = str(reason or "candidate_seen")
    checkpoint["sequence"] = int(checkpoint.get("sequence") or 0) + 1
    _ct_checkpoint_emit(
        checkpoint,
        "follow_target_checkpoint_updated",
        reason=str(reason or "candidate_seen"),
        candidate_username=key,
    )


def _ct_checkpoint_mark_rejected(
    checkpoint: dict[str, Any],
    candidate_username: str,
    *,
    reason: str,
    source_phase: str = "",
) -> None:
    key = _norm_ig_handle(candidate_username)
    if not key:
        return
    stable = _normalize_target_rejection_reason(reason)
    rejected = dict(checkpoint.get("last_rejected_candidate_usernames") or {})
    if key not in rejected:
        checkpoint["rejected_count"] = int(checkpoint.get("rejected_count") or 0) + 1
    rejected[key] = stable
    checkpoint["last_rejected_candidate_usernames"] = rejected
    if stable == "private_account":
        checkpoint["private_rejected_count"] = int(
            checkpoint.get("private_rejected_count") or 0
        ) + 1
        private_rejected = list(checkpoint.get("last_private_rejected_usernames") or [])
        if key not in private_rejected:
            private_rejected.append(key)
        checkpoint["last_private_rejected_usernames"] = private_rejected[-96:]
    _ct_checkpoint_mark_seen(
        checkpoint,
        key,
        reason=f"rejected:{stable}",
    )
    _ct_checkpoint_emit(
        checkpoint,
        "follow_target_checkpoint_updated",
        reason=stable,
        candidate_username=key,
        source_phase=str(source_phase or "")[:80],
    )


def _ct_checkpoint_mark_followed(
    checkpoint: dict[str, Any],
    candidate_username: str,
    *,
    reason: str = "follow_verified",
) -> None:
    key = _norm_ig_handle(candidate_username)
    if not key:
        return
    checkpoint["last_followed_candidate_username"] = key
    checkpoint["last_successful_candidate_at"] = _ct_checkpoint_utc_now_iso()
    checkpoint["last_successful_candidate_at_mono"] = time.perf_counter()
    checkpoint["followed_count"] = int(checkpoint.get("followed_count") or 0) + 1
    _ct_checkpoint_mark_seen(checkpoint, key, reason=str(reason or "follow_verified"))


def _ct_checkpoint_update_visible_window(
    checkpoint: dict[str, Any],
    candidates: list[Any],
    *,
    scroll_used: int,
    loop_iteration: int,
    reason: str,
) -> None:
    usernames = [
        _norm_ig_handle(str(c.get("username") or c.get("resolved_username_hint") or ""))
        for c in candidates
        if _norm_ig_handle(str(c.get("username") or c.get("resolved_username_hint") or ""))
    ]
    checkpoint["last_scroll_index"] = int(scroll_used)
    checkpoint["last_visible_usernames"] = usernames[:24]
    committed_meta = followers_session_committed_meta()
    checkpoint["last_visible_surface_generation"] = float(
        committed_meta.get("followers_list_committed_at") or 0.0
    )
    checkpoint["updated_at"] = _ct_checkpoint_utc_now_iso()
    checkpoint["updated_at_mono"] = time.perf_counter()
    checkpoint["updated_at_epoch"] = time.time()
    checkpoint["stale_after"] = _ct_checkpoint_stale_after_iso()
    checkpoint["checkpoint_reason"] = str(reason or "visible_window_updated")
    checkpoint["last_checkpoint_reason"] = str(reason or "visible_window_updated")
    checkpoint["sequence"] = int(checkpoint.get("sequence") or 0) + 1
    event = (
        "follow_target_checkpoint_created"
        if int(checkpoint.get("sequence") or 0) == 1
        else "follow_target_checkpoint_updated"
    )
    _ct_checkpoint_emit(
        checkpoint,
        event,
        reason=str(reason or "visible_window_updated"),
        loop_iteration=int(loop_iteration),
        visible_count=len(usernames),
        sample_usernames=usernames[:8],
    )


def _ct_checkpoint_should_reuse_post_return_visible_window(
    checkpoint: dict[str, Any],
    *,
    source_username: str,
    account_id: str,
    run_id: str,
    scroll_used: int,
    visual_loop_state: dict[str, Any],
) -> tuple[bool, str]:
    if not _ct_checkpoint_enabled():
        return False, "checkpoint_disabled"
    if not bool(visual_loop_state.get("post_return_picker_refresh_pending")):
        return False, "post_return_proof_missing"
    ok, reject_reason = _ct_checkpoint_validate(
        checkpoint,
        source_username=source_username,
        account_id=account_id,
        run_id=run_id,
    )
    if not ok:
        return False, reject_reason
    if not followers_session_list_committed_open_for(source_username):
        return False, "followers_surface_not_committed"
    meta = visual_loop_state.get("post_return_picker_refresh_meta")
    if not isinstance(meta, dict):
        return False, "picker_refresh_meta_missing"
    meta_source = _norm_ig_handle(str(meta.get("source_username") or ""))
    want_source = _norm_ig_handle(str(source_username or ""))
    if meta_source and want_source and meta_source != want_source:
        return False, "post_return_source_mismatch"
    return_method = str(meta.get("return_method") or "")
    if return_method not in _CT_CHECKPOINT_POST_RETURN_SAFE_METHODS:
        return False, "return_method_not_reusable"
    visible = [
        _norm_ig_handle(str(u))
        for u in (checkpoint.get("last_visible_usernames") or [])
        if _norm_ig_handle(str(u))
    ]
    if not visible:
        return False, "checkpoint_visible_window_missing"
    if _ct_checkpoint_last_scroll_index(checkpoint) != int(scroll_used):
        return False, "checkpoint_scroll_index_mismatch"
    checkpoint_age_ms = _ct_checkpoint_age_ms(checkpoint)
    proof_at = float(meta.get("post_return_proof_at_mono") or 0.0)
    proof_age_ms = (
        round((time.perf_counter() - proof_at) * 1000.0, 2) if proof_at > 0.0 else -1.0
    )
    proof_fresh = 0.0 <= proof_age_ms <= 15_000.0
    if checkpoint_age_ms > _CT_CHECKPOINT_POST_RETURN_REUSE_MS and not proof_fresh:
        return False, "checkpoint_visible_window_stale"
    return True, "checkpoint_visible_window_fresh"


def _ct_checkpoint_should_skip_post_return_picker_refresh(
    checkpoint: dict[str, Any],
    *,
    source_username: str,
    account_id: str,
    run_id: str,
    scroll_used: int,
    visual_loop_state: dict[str, Any],
) -> tuple[bool, str]:
    return _ct_checkpoint_should_reuse_post_return_visible_window(
        checkpoint,
        source_username=source_username,
        account_id=account_id,
        run_id=run_id,
        scroll_used=scroll_used,
        visual_loop_state=visual_loop_state,
    )


def _ct_checkpoint_should_skip_post_return_list_revalidation(
    checkpoint: dict[str, Any],
    *,
    source_username: str,
    account_id: str,
    run_id: str,
    scroll_used: int,
    visual_loop_state: dict[str, Any],
    reuse_det: dict[str, Any] | None,
    committed_age_ms: float,
) -> tuple[bool, str]:
    ok, reason = _ct_checkpoint_should_reuse_post_return_visible_window(
        checkpoint,
        source_username=source_username,
        account_id=account_id,
        run_id=run_id,
        scroll_used=scroll_used,
        visual_loop_state=visual_loop_state,
    )
    if not ok:
        return False, reason
    if not isinstance(reuse_det, dict) or not reuse_det:
        return False, "snapshot_reuse_det_missing"
    if not bool(reuse_det.get("is_followers_list")):
        return False, "snapshot_not_followers_list"
    if str(reuse_det.get("open_detection_method") or "") != "own_unified_follow_list":
        return False, "snapshot_open_method_not_reusable"
    try:
        candidate_count = int(reuse_det.get("candidate_username_count") or 0)
    except Exception:
        candidate_count = 0
    if candidate_count <= 0:
        return False, "snapshot_candidate_count_zero"
    if float(committed_age_ms) < 0.0 or float(committed_age_ms) > 8_500.0:
        return False, "committed_surface_proof_stale"
    return True, "checkpoint_visible_window_fresh"


def _ct_checkpoint_emit_post_return_list_revalidation_skipped(
    checkpoint: dict[str, Any],
    *,
    source_username: str,
    reason: str,
    scroll_used: int,
    committed_age_ms: float,
    open_detection_method: str,
) -> None:
    log(
        "info",
        "followers_post_return_list_revalidation_skipped_checkpoint_fresh",
        source_profile_username=source_username,
        reason=str(reason or "checkpoint_visible_window_fresh"),
        scroll_index=int(scroll_used),
        checkpoint_age_ms=_ct_checkpoint_age_ms(checkpoint),
        committed_age_ms=float(committed_age_ms),
        visible_count=len(checkpoint.get("last_visible_usernames") or []),
        seen_count=int(checkpoint.get("seen_count") or 0),
        rejected_count=int(checkpoint.get("rejected_count") or 0),
        followed_count=int(checkpoint.get("followed_count") or 0),
        open_detection_method=str(open_detection_method or ""),
        safe_to_recollect=True,
        fallback_used=False,
    )


def _ct_checkpoint_known_keys(checkpoint: dict[str, Any]) -> set[str]:
    known: set[str] = set()
    for u in checkpoint.get("last_seen_candidate_usernames") or []:
        k = _norm_ig_handle(str(u))
        if k:
            known.add(k)
    for u in (checkpoint.get("last_rejected_candidate_usernames") or {}).keys():
        k = _norm_ig_handle(str(u))
        if k:
            known.add(k)
    followed = _norm_ig_handle(str(checkpoint.get("last_followed_candidate_username") or ""))
    if followed:
        known.add(followed)
    return known


def _ct_checkpoint_fast_skip_reason(
    checkpoint: dict[str, Any],
    candidate_key: str,
    *,
    runtime_followed: set[str],
    runtime_seen: set[str],
    runtime_skipped: set[str],
) -> str:
    rejected = dict(checkpoint.get("last_rejected_candidate_usernames") or {})
    if candidate_key in rejected:
        return str(rejected.get(candidate_key) or "checkpoint_rejected")
    if candidate_key in runtime_followed:
        return "runtime_followed"
    if candidate_key in runtime_skipped:
        return "runtime_skipped"
    if candidate_key in runtime_seen:
        return "runtime_seen"
    followed = _norm_ig_handle(str(checkpoint.get("last_followed_candidate_username") or ""))
    if followed and candidate_key == followed:
        return "checkpoint_followed"
    return ""


def _ct_checkpoint_should_fast_skip_visible_candidate(
    checkpoint: dict[str, Any],
    candidate: dict[str, Any],
    *,
    runtime_followed: set[str],
    runtime_seen: set[str],
    runtime_skipped: set[str],
) -> tuple[bool, str]:
    if not _ct_checkpoint_enabled():
        return False, ""
    key = _norm_ig_handle(
        str(candidate.get("username") or candidate.get("resolved_username_hint") or "")
    )
    if not key:
        return False, ""
    visible = {
        _norm_ig_handle(str(u))
        for u in (checkpoint.get("last_visible_usernames") or [])
        if _norm_ig_handle(str(u))
    }
    if visible and key not in visible:
        return False, ""
    reason = _ct_checkpoint_fast_skip_reason(
        checkpoint,
        key,
        runtime_followed=runtime_followed,
        runtime_seen=runtime_seen,
        runtime_skipped=runtime_skipped,
    )
    if not reason:
        return False, ""
    return True, reason


def _ct_checkpoint_visible_window_all_known(
    checkpoint: dict[str, Any],
    candidates: list[Any],
    *,
    runtime_followed: set[str],
    runtime_seen: set[str],
    runtime_skipped: set[str],
) -> bool:
    if not candidates:
        return False
    for c in candidates:
        key = _norm_ig_handle(
            str(c.get("username") or c.get("resolved_username_hint") or "")
        )
        if not key:
            return False
        if not _ct_checkpoint_fast_skip_reason(
            checkpoint,
            key,
            runtime_followed=runtime_followed,
            runtime_seen=runtime_seen,
            runtime_skipped=runtime_skipped,
        ):
            return False
    return True


def _ct_checkpoint_plan_scroll_resume(
    checkpoint: dict[str, Any],
    *,
    scroll_used: int,
    source_username: str,
    account_id: str,
    run_id: str,
    candidates: list[Any],
    runtime_followed: set[str],
    runtime_seen: set[str],
    runtime_skipped: set[str],
) -> tuple[int | None, bool, str]:
    ok, reject_reason = _ct_checkpoint_validate(
        checkpoint,
        source_username=source_username,
        account_id=account_id,
        run_id=run_id,
    )
    if not ok:
        _ct_checkpoint_emit(
            checkpoint,
            "follow_target_checkpoint_rejected",
            reason=reject_reason,
            fallback_used=True,
            safe_to_resume=False,
        )
        return None, False, reject_reason
    if not _ct_checkpoint_visible_window_all_known(
        checkpoint,
        candidates,
        runtime_followed=runtime_followed,
        runtime_seen=runtime_seen,
        runtime_skipped=runtime_skipped,
    ):
        return None, False, "visible_window_has_unknown_candidate"
    last_idx = int(checkpoint.get("last_scroll_index") if checkpoint.get("last_scroll_index") is not None else -1)
    resume_idx = max(int(scroll_used), last_idx + _CT_CHECKPOINT_SCROLL_RESUME_OFFSET)
    if resume_idx <= int(scroll_used):
        resume_idx = int(scroll_used) + _CT_CHECKPOINT_SCROLL_RESUME_OFFSET
    checkpoint["scroll_resume_planned_index"] = resume_idx
    _ct_checkpoint_emit(
        checkpoint,
        "follow_target_scroll_resume_planned",
        reason="visible_window_all_known",
        resume_scroll_index=resume_idx,
        scroll_index=int(scroll_used),
        safe_to_resume=True,
        fallback_used=False,
    )
    return resume_idx, True, "visible_window_all_known"


def _followers_visible_window_exhausted_scroll_required(
    *,
    candidates_len: int,
    visible_skip_count: int,
    follows_completed: int,
    follows_goal_effective: int | None,
    scroll_used: int,
    max_scroll: int,
    should_stop_scrolling: bool = False,
) -> bool:
    """True when all visible rows were skipped but quota and scroll budget remain."""
    if bool(should_stop_scrolling):
        return False
    if int(candidates_len or 0) <= 0:
        return False
    if int(visible_skip_count or 0) < int(candidates_len or 0):
        return False
    if follows_goal_effective is not None and int(follows_completed or 0) >= int(
        follows_goal_effective or 0
    ):
        return False
    if int(scroll_used or 0) >= int(max_scroll or 0):
        return False
    return True


def _followers_snapshot_viewport_exhausted(
    candidates: list[Any] | None,
) -> bool:
    """True only when a reused immutable snapshot contains no unseen row."""
    rows = [row for row in list(candidates or []) if isinstance(row, dict)]
    return bool(rows) and all(bool(row.get("already_seen_runtime")) for row in rows)


def _followers_post_scroll_failure_continuation_action(
    continuation: dict[str, Any] | None,
) -> str:
    """Classify the one fresh continuation probe after a rejected depth move."""
    state = str((continuation or {}).get("state") or "")
    if state == "PRIMARY_ROWS_AVAILABLE":
        return "continue_primary_rows"
    if state == "EXPAND_PRIMARY_LIST_AVAILABLE":
        return "expand_primary_list"
    return "rotate_safe"


def _followers_visible_window_scroll_strategy(*, scroll_used: int) -> dict[str, Any]:
    attempt_index = max(1, int(scroll_used or 0) + 1)
    if attempt_index == 1:
        return {
            "strategy": "soft_initial",
            "scroll_profile": "soft_initial",
            "distance_ratio": 0.25,
            "expected_new_rows_min": 7,
            "reason": "visible_window_exhausted_first_scroll_soft",
            "scroll_attempt_index": attempt_index,
        }
    if attempt_index == 2:
        return {
            "strategy": "soft_retry",
            "scroll_profile": "soft_retry",
            "distance_ratio": 0.27,
            "expected_new_rows_min": 7,
            "reason": "visible_window_exhausted_second_scroll_soft",
            "scroll_attempt_index": attempt_index,
        }
    return {
        "strategy": "strong_search",
        "scroll_profile": "accelerated_skip_streak",
        "distance_ratio": 0.56,
        "expected_new_rows_min": 7,
        "reason": "visible_window_exhausted_after_two_soft_scrolls",
        "scroll_attempt_index": attempt_index,
    }


def _followers_pre_scroll_contract_decision(
    continuation: dict[str, Any],
    *,
    followers_list_proved: bool,
    visual_evidence: dict[str, Any] | None = None,
) -> str:
    """Return the no-gesture decision after the visible viewport is exhausted."""
    state = str(continuation.get("state") or "")
    visual = visual_evidence if isinstance(visual_evidence, dict) else {}
    visual_hard_boundary = bool(
        visual.get("hard_boundary_proved")
        or visual.get("suggestions_boundary_proved")
        or visual.get("suggestions_only_proved")
    )
    if state == "EXPAND_PRIMARY_LIST_AVAILABLE":
        return "expand_primary_list"
    if bool(continuation.get("is_boundary")) or visual_hard_boundary:
        return "stop_hard_boundary"
    # This helper is called only after every candidate in the current visible
    # viewport has already been processed or safely rejected. Seeing those
    # same primary rows again proves the followers surface; it must not send
    # the engine back around the same viewport without a scroll.
    if state == "PRIMARY_ROWS_AVAILABLE":
        if followers_list_proved and int(continuation.get("primary_row_count") or 0) > 0:
            return "allow_canonical_scroll"
        return "stop_ambiguous_surface"
    if (
        followers_list_proved
        and int(continuation.get("primary_row_count") or 0) > 0
        and not bool(continuation.get("see_more_visible"))
        and not bool(continuation.get("is_boundary"))
    ):
        return "allow_canonical_scroll"
    return "stop_ambiguous_surface"


def _new_candidate_follow_decision(
    *,
    follower_username: str = "",
    visual_candidate_id: str = "",
) -> dict[str, Any]:
    """Single terminal follow decision passed through the candidate pipeline."""
    from follow_state_contract import new_candidate_follow_decision

    return new_candidate_follow_decision(
        follower_username=follower_username,
        visual_candidate_id=visual_candidate_id,
    )


def _candidate_follow_decision_block(
    decision: dict[str, Any],
    *,
    reason: str,
    source: str,
    private_detected: bool = False,
) -> dict[str, Any]:
    from follow_state_contract import candidate_follow_decision_block

    return candidate_follow_decision_block(
        decision,
        reason=reason,
        source=source,
        private_detected=private_detected,
    )


def _candidate_follow_decision_apply_source(
    decision: dict[str, Any],
    source_decision: dict[str, Any] | None,
    *,
    source: str,
) -> dict[str, Any]:
    from follow_state_contract import candidate_follow_decision_apply_source

    return candidate_follow_decision_apply_source(
        decision, source_decision, source=source
    )


def _candidate_follow_decision_blocks_follow(decision: dict[str, Any] | None) -> bool:
    from follow_state_contract import candidate_follow_decision_blocks_follow

    return candidate_follow_decision_blocks_follow(decision)


def _candidate_follow_decision_assert_follow_allowed(
    decision: dict[str, Any],
    *,
    source: str = "final_pre_follow_guard",
) -> tuple[bool, str, dict[str, Any]]:
    """Follow State Contract terminal gate before perform_follow_safe."""
    from follow_state_contract import FollowContext

    ctx = FollowContext.from_decision_dict(decision)
    if ctx.blocks_follow():
        _reason = str(ctx.blocked_reason or "follow_blocked")
        if ctx.private_detected:
            _reason = "private_account"
        return False, _reason, ctx.to_decision_dict()
    ctx.allow_follow(source=source)
    ok, deny = ctx.assert_can_perform_follow_safe()
    return ok, deny, ctx.to_decision_dict()


def _session_total_interactions_cap_exceeded() -> bool:
    lim = int(getattr(config, "SESSION_TOTAL_INTERACTIONS_LIMIT", 0) or 0)
    if lim <= 0:
        return False
    return _SESSION_COUNTERS["interactions"] >= lim


def _session_successful_interactions_cap_exceeded() -> bool:
    lim = int(getattr(config, "SESSION_TOTAL_SUCCESSFUL_INTERACTIONS_LIMIT", 0) or 0)
    if lim <= 0:
        return False
    return _SESSION_COUNTERS["successful_interactions"] >= lim


def _session_strict_completion_exit_code() -> int | None:
    if not getattr(config, "SESSION_STRICT_PHASE_COMPLETION", False):
        return None
    caps = [
        int(getattr(config, "SESSION_TOTAL_FOLLOWS_CAP", 0) or 0),
        int(getattr(config, "SESSION_FOLLOW_LIMIT", 0) or 0),
    ]
    pos = [c for c in caps if c > 0]
    if pos and _SESSION_COUNTERS["follows"] < min(pos):
        log(
            "warning",
            "session_strict_incomplete",
            reason="follow_quota_unmet",
            follows=_SESSION_COUNTERS["follows"],
            required=min(pos),
        )
        return 53
    til = int(getattr(config, "SESSION_TOTAL_INTERACTIONS_LIMIT", 0) or 0)
    if til > 0 and _SESSION_COUNTERS["interactions"] < til:
        log(
            "warning",
            "session_strict_incomplete",
            reason="interactions_quota_unmet",
            interactions=_SESSION_COUNTERS["interactions"],
            required=til,
        )
        return 54
    return None


def _social_memory_load_and_evaluate(
    *,
    target_username: str,
    source_profile: str,
    account_id: str,
    run_id: str,
    supabase_mode: bool,
) -> social_memory.FollowEligibility:
    db_row = None
    if supabase_mode and account_id and getattr(config, "SOCIAL_MEMORY_ENABLED", True):
        db_row = _safe_supabase_call(
            "load_interacted_user",
            account_id,
            target_username,
            source_profile or "",
        )
        log(
            "info",
            "social_memory_loaded",
            target_username=target_username,
            source_profile=source_profile or "",
            has_row=bool(db_row),
        )
    return social_memory.evaluate_follow_eligibility(
        target_username=target_username,
        source_profile=source_profile or "",
        db_row=db_row,
        runtime_followed=_RUNTIME_FOLLOWED_USERNAMES,
        runtime_unfollowed=_RUNTIME_UNFOLLOWED_USERNAMES,
        runtime_interacted=_RUNTIME_INTERACTED_USERNAMES,
        runtime_skipped=_RUNTIME_SKIPPED_USERNAMES,
        config=config,
    )


def _persist_social_memory_follow_block(
    *,
    elig: social_memory.FollowEligibility,
    account_id: str,
    run_id: str,
    supabase_mode: bool,
    target_username: str,
    source_profile: str,
) -> None:
    if not (supabase_mode and account_id and getattr(config, "SOCIAL_MEMORY_ENABLED", True)):
        return
    _safe_supabase_call(
        "record_interaction_skip_memory",
        account_id,
        target_username,
        source_profile or "",
        skip_reason=elig.reason,
        run_id=run_id or None,
        session_id=_SESSION_SOCIAL_ID or None,
        lifecycle_state=elig.interaction_state,
    )
    log(
        "info",
        "social_memory_updated",
        target_username=target_username,
        source_profile=source_profile or "",
        kind="skip_block",
        reason=elig.reason,
    )


